import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor fused_attention_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
#include <math.h>

using namespace cute;

// Fused attention kernel:
//   S = scale * Q @ K^T   (contract over head-dim D)
//   P = softmax_row(S)    (over full key dimension SEQ)
//   O = P @ V             (contract over key dimension SEQ, produce D outputs)
//
// One block handles a tile of BLOCK_M query rows for one (batch,head) pair.
// The full key/value sequence (SEQ) is kept resident logically (S/P buffer in
// shared memory), while the head-dimension D is streamed in DK/DV sized
// chunks through shared memory to bound shared-memory usage.
template <typename T, int BLOCK_M, int DK, int DV, int THREADS>
__global__ void fused_attention_kernel(
    const T* __restrict__ Qg,
    const T* __restrict__ Kg,
    const T* __restrict__ Vg,
    T* __restrict__ Og,
    int BH, int SEQ, int D, float scale)
{
    int bh     = blockIdx.y;
    int m_tile = blockIdx.x;
    int m0     = m_tile * BLOCK_M;
    int m_count = min(BLOCK_M, SEQ - m0);
    if (m_count <= 0) return;

    const T* Qb = Qg + (size_t)bh * (size_t)SEQ * (size_t)D;
    const T* Kb = Kg + (size_t)bh * (size_t)SEQ * (size_t)D;
    const T* Vb = Vg + (size_t)bh * (size_t)SEQ * (size_t)D;
    T*       Ob = Og + (size_t)bh * (size_t)SEQ * (size_t)D;

    // Global tensors described with CuTe (row-major: D contiguous)
    auto gQ = make_tensor(make_gmem_ptr(Qb), make_shape(SEQ, D), make_stride(D, 1));
    auto gK = make_tensor(make_gmem_ptr(Kb), make_shape(SEQ, D), make_stride(D, 1));
    auto gV = make_tensor(make_gmem_ptr(Vb), make_shape(SEQ, D), make_stride(D, 1));
    auto gO = make_tensor(make_gmem_ptr(Ob), make_shape(SEQ, D), make_stride(D, 1));

    extern __shared__ unsigned char smem_raw[];

    size_t qk_bytes   = (size_t)BLOCK_M * DK * sizeof(T) + (size_t)SEQ * DK * sizeof(T);
    size_t v_bytes    = (size_t)SEQ * DV * sizeof(T);
    size_t swap_bytes = qk_bytes > v_bytes ? qk_bytes : v_bytes;
    swap_bytes = (swap_bytes + 7) & ~size_t(7);

    T*     Q_tile_ptr = reinterpret_cast<T*>(smem_raw);
    T*     K_tile_ptr = Q_tile_ptr + BLOCK_M * DK;
    float* S_ptr      = reinterpret_cast<float*>(smem_raw + swap_bytes);

    auto sQ = make_tensor(make_smem_ptr(Q_tile_ptr), make_shape(BLOCK_M, DK), make_stride(DK, 1));
    auto sK = make_tensor(make_smem_ptr(K_tile_ptr), make_shape(SEQ, DK), make_stride(DK, 1));
    auto sS = make_tensor(make_smem_ptr(S_ptr), make_shape(BLOCK_M, SEQ), make_stride(SEQ, 1));

    int tid = threadIdx.x;

    // zero S accumulator
    for (int e = tid; e < BLOCK_M * SEQ; e += THREADS) {
        int m = e / SEQ, n = e % SEQ;
        sS(m, n) = 0.0f;
    }
    __syncthreads();

    // ---- Phase 1: S = Q @ K^T (accumulate raw dot products) ----
    for (int d0 = 0; d0 < D; d0 += DK) {
        int dk_count = min(DK, D - d0);

        for (int e = tid; e < BLOCK_M * DK; e += THREADS) {
            int m = e / DK, k = e % DK;
            T val = T(0.0f);
            if (m < m_count && k < dk_count) {
                val = gQ(m0 + m, d0 + k);
            }
            sQ(m, k) = val;
        }
        for (int e = tid; e < SEQ * DK; e += THREADS) {
            int n = e / DK, k = e % DK;
            T val = T(0.0f);
            if (k < dk_count) {
                val = gK(n, d0 + k);
            }
            sK(n, k) = val;
        }
        __syncthreads();

        for (int e = tid; e < BLOCK_M * SEQ; e += THREADS) {
            int m = e / SEQ, n = e % SEQ;
            if (m < m_count) {
                float partial = 0.0f;
                #pragma unroll
                for (int k = 0; k < DK; ++k) {
                    partial += float(sQ(m, k)) * float(sK(n, k));
                }
                sS(m, n) += partial;
            }
        }
        __syncthreads();
    }

    // scale
    for (int e = tid; e < BLOCK_M * SEQ; e += THREADS) {
        int m = e / SEQ, n = e % SEQ;
        sS(m, n) = sS(m, n) * scale;
    }
    __syncthreads();

    // ---- Phase 2: row-wise softmax over full key dimension ----
    for (int m = tid; m < m_count; m += THREADS) {
        float maxv = -INFINITY;
        for (int n = 0; n < SEQ; ++n) {
            maxv = fmaxf(maxv, sS(m, n));
        }
        float sum = 0.0f;
        for (int n = 0; n < SEQ; ++n) {
            float e = __expf(sS(m, n) - maxv);
            sS(m, n) = e;
            sum += e;
        }
        float inv = 1.0f / sum;
        for (int n = 0; n < SEQ; ++n) {
            sS(m, n) = sS(m, n) * inv;
        }
    }
    __syncthreads();

    // ---- Phase 3: O = P @ V, streaming V over the head dimension ----
    T* V_tile_ptr = reinterpret_cast<T*>(smem_raw);
    auto sV = make_tensor(make_smem_ptr(V_tile_ptr), make_shape(SEQ, DV), make_stride(DV, 1));

    for (int d0 = 0; d0 < D; d0 += DV) {
        int dv_count = min(DV, D - d0);

        for (int e = tid; e < SEQ * DV; e += THREADS) {
            int n = e / DV, dv = e % DV;
            T val = T(0.0f);
            if (dv < dv_count) {
                val = gV(n, d0 + dv);
            }
            sV(n, dv) = val;
        }
        __syncthreads();

        for (int e = tid; e < BLOCK_M * DV; e += THREADS) {
            int m = e / DV, dv = e % DV;
            if (m < m_count && dv < dv_count) {
                float acc = 0.0f;
                #pragma unroll 4
                for (int n = 0; n < SEQ; ++n) {
                    acc += sS(m, n) * float(sV(n, dv));
                }
                gO(m0 + m, d0 + dv) = T(acc);
            }
        }
        __syncthreads();
    }
}

torch::Tensor fused_attention_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V) {
    TORCH_CHECK(Q.is_cuda() && K.is_cuda() && V.is_cuda(), "Q,K,V must be CUDA tensors");
    TORCH_CHECK(Q.scalar_type() == at::kHalf && K.scalar_type() == at::kHalf && V.scalar_type() == at::kHalf,
                "Only float16 supported");
    TORCH_CHECK(Q.dim() == 4, "Expect [B,H,S,D]");
    TORCH_CHECK(Q.sizes() == K.sizes() && Q.sizes() == V.sizes(), "Q,K,V must have same shape");

    auto Qc = Q.contiguous();
    auto Kc = K.contiguous();
    auto Vc = V.contiguous();

    int B = (int)Qc.size(0);
    int H = (int)Qc.size(1);
    int SEQ = (int)Qc.size(2);
    int D = (int)Qc.size(3);
    int BH = B * H;

    auto O = torch::empty_like(Qc);

    constexpr int BLOCK_M = 16;
    constexpr int DK = 64;
    constexpr int DV = 64;
    constexpr int THREADS = 256;

    float scale = 1.0f / sqrtf((float)D);

    size_t qk_bytes = (size_t)BLOCK_M * DK * sizeof(cute::half_t) + (size_t)SEQ * DK * sizeof(cute::half_t);
    size_t v_bytes  = (size_t)SEQ * DV * sizeof(cute::half_t);
    size_t swap_bytes = qk_bytes > v_bytes ? qk_bytes : v_bytes;
    swap_bytes = (swap_bytes + 7) & ~size_t(7);
    size_t s_bytes = (size_t)BLOCK_M * SEQ * sizeof(float);
    size_t total_smem = swap_bytes + s_bytes;

    dim3 grid((SEQ + BLOCK_M - 1) / BLOCK_M, BH);
    dim3 block(THREADS);

    auto kernel = fused_attention_kernel<cute::half_t, BLOCK_M, DK, DV, THREADS>;
    int device_id = 0;
    cudaGetDevice(&device_id);
    int max_smem_optin = 0;
    cudaDeviceGetAttribute(&max_smem_optin, cudaDevAttrMaxSharedMemoryPerBlockOptin, device_id);
    TORCH_CHECK((size_t)max_smem_optin >= total_smem,
                "fused_attention_kernel: requested shared memory (", total_smem,
                " bytes) exceeds device limit (", max_smem_optin, " bytes)");
    cudaError_t attr_err = cudaFuncSetAttribute(kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)total_smem);
    TORCH_CHECK(attr_err == cudaSuccess, "cudaFuncSetAttribute failed: ", cudaGetErrorString(attr_err));

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    kernel<<<grid, block, total_smem, stream>>>(
        reinterpret_cast<const cute::half_t*>(Qc.data_ptr<at::Half>()),
        reinterpret_cast<const cute::half_t*>(Kc.data_ptr<at::Half>()),
        reinterpret_cast<const cute::half_t*>(Vc.data_ptr<at::Half>()),
        reinterpret_cast<cute::half_t*>(O.data_ptr<at::Half>()),
        BH, SEQ, D, scale);

    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "fused_attention_kernel launch failed: ", cudaGetErrorString(err));

    return O;
}
"""

fused_attention_ext = load_inline(
    name="cute_fused_attention_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["fused_attention_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/root/cutegen_test/cutegen/cutlass/include",
        "/root/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self._ext = fused_attention_ext

    def forward(self, Q: torch.Tensor, K: torch.Tensor, V: torch.Tensor) -> torch.Tensor:
        return self._ext.fused_attention_forward(Q, K, V)

